  1	package hotel.reservations;
  2	
  3	import hotel.documents.BookingReceipt;
  4	import hotel.documents.Invoice;
  5	import hotel.documents.ReservationReceipt;
  6	import hotel.documents.TextFormat;
  7	import hotel.messages.EmailSender;
  8	import hotel.rooms.Room;
  9	import hotel.rooms.Rooms;
 10	import java.math.BigDecimal;
 11	
 12	/** The life of a reservation: created, confirmed (paid), checked in, checked out, or cancelled. */
 13	public final class ReservationService {
 14	
 15	    static final String HOTEL_NAME = "Pousada Maré Alta";
 16	
 17	    private final Rooms rooms;
 18	    private final ReservationStore store;
 19	    private final PriceCalculator priceCalculator;
 20	    private final EmailSender emailSender;
 21	
 22	    public ReservationService(
 23	            Rooms rooms, ReservationStore store, PriceCalculator priceCalculator, EmailSender emailSender) {
 24	        this.rooms = rooms;
 25	        this.store = store;
 26	        this.priceCalculator = priceCalculator;
 27	        this.emailSender = emailSender;
 28	    }
 29	
 30	    public synchronized Reservation create(NewReservation request) {
 31	        if (!request.checkOut().isAfter(request.checkIn())) {
 32	            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
 33	        }
 34	        if (request.guests() < 1) {
 35	            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
 36	        }
 37	        Room room = rooms.find(request.roomNumber())
 38	                .orElseThrow(() -> new HotelException(
 39	                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
 40	        if (request.guests() > room.capacity()) {
 41	            throw new HotelException(
 42	                    ErrorCode.CAPACITY_EXCEEDED,
 43	                    "room " + room.number() + " takes at most " + room.capacity() + " guests");
 44	        }
 45	        if (store.isRoomTaken(room.number(), request.checkIn(), request.checkOut())) {
 46	            throw new HotelException(
 47	                    ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
 48	        }
 49	        Price price = priceCalculator.calculate(room, request.checkIn(), request.checkOut(), request.ratePlan());
 50	        return store.add(request, price);
 51	    }
 52	
 53	    public Reservation find(long reservationId) {
 54	        return store.find(reservationId)
 55	                .orElseThrow(() -> new HotelException(
 56	                        ErrorCode.RESERVATION_NOT_FOUND, "reservation " + reservationId + " does not exist"));
 57	    }
 58	
 59	    public String getDocumentText(Reservation reservation) {
 60	        return generateDocumentText(reservation, roomOf(reservation));
 61	    }
 62	
 63	    /** The guest paid: the reservation is confirmed and the guest gets the receipt by e-mail. */
 64	    public synchronized Reservation confirm(long reservationId) {
 65	        Reservation reservation = find(reservationId);
 66	        if (reservation.status() != ReservationStatus.PENDING) {
 67	            throw notAllowed(reservation, "confirm");
 68	        }
 69	        reservation.confirmPayment();
 70	        store.update(reservation);
 71	        String documentText = generateDocumentText(reservation, roomOf(reservation));
 72	        emailSender.send(
 73	                reservation.guest().email(),
 74	                "Reserva confirmada - " + HOTEL_NAME,
 75	                confirmationEmailBody(reservation, documentText));
 76	        return reservation;
 77	    }
 78	
 79	    /**
 80	     * Cancelling before the stay starts. What was paid comes back according to the rate plan (a pending
 81	     * reservation was never paid, so nothing comes back).
 82	     */
 83	    public synchronized Reservation cancel(long reservationId) {
 84	        Reservation reservation = find(reservationId);
 85	        if (reservation.status() != ReservationStatus.PENDING
 86	                && reservation.status() != ReservationStatus.CONFIRMED) {
 87	            throw notAllowed(reservation, "cancel");
 88	        }
 89	        BigDecimal refund = switch (reservation.ratePlan()) {
 90	            case STANDARD -> reservation.amountPaid();
 91	            case NON_REFUNDABLE -> PriceCalculator.cents(BigDecimal.ZERO);
 92	        };
 93	        reservation.cancel(refund);
 94	        store.update(reservation);
 95	        return reservation;
 96	    }
 97	
 98	    public synchronized Reservation checkIn(long reservationId) {
 99	        Reservation reservation = find(reservationId);
100	        if (reservation.status() != ReservationStatus.CONFIRMED) {
101	            throw notAllowed(reservation, "check in");
102	        }
103	        reservation.changeStatus(ReservationStatus.CHECKED_IN);
104	        store.update(reservation);
105	        return reservation;
106	    }
107	
108	    /** The guest leaves: the stay is closed and the final receipt is handed over. */
109	    public synchronized Object checkOut(long reservationId) {
110	        Reservation reservation = find(reservationId);
111	        if (reservation.status() != ReservationStatus.CHECKED_IN) {
112	            throw notAllowed(reservation, "check out");
113	        }
114	        reservation.changeStatus(ReservationStatus.CHECKED_OUT);
115	        store.update(reservation);
116	        return generateDocument(reservation, roomOf(reservation));
117	    }
118	
119	    /** A copy of the receipt, for a guest who lost it. Only paid reservations have one. */
120	    public Object receiptCopy(long reservationId) {
121	        Reservation reservation = find(reservationId);
122	        if (!reservation.isPaid()) {
123	            throw notAllowed(reservation, "issue a receipt for");
124	        }
125	        return generateDocument(reservation, roomOf(reservation));
126	    }
127	
128	    private Room roomOf(Reservation reservation) {
129	        return rooms.find(reservation.roomNumber()).orElseThrow();
130	    }
131	
132	    private Object generateDocument(Reservation reservation, Room room) {
133	        if (reservation.guest().cpf() != null) {
134	            return new ReservationReceipt(reservation, room);
135	        } else if (reservation.guest().companyCnpj() != null) {
136	            BigDecimal issRetained = reservation.price().subtotal()
137	                    .multiply(PriceCalculator.cents(new BigDecimal("5")))
138	                    .divide(PriceCalculator.cents(new BigDecimal("100")));
139	            return new Invoice(reservation, room, issRetained);
140	        } else {
141	            return new BookingReceipt(reservation, room);
142	        }
143	    }
144	
145	    private String generateDocumentText(Reservation reservation, Room room) {
146	        if (reservation.guest().cpf() != null) {
147	            return generateReservationReceiptText(reservation, room);
148	        } else if (reservation.guest().companyCnpj() != null) {
149	            return generateInvoiceText(reservation, room);
150	        } else {
151	            return generateBookingReceiptText(reservation, room);
152	        }
153	    }
154	
155	    private static String generateReservationReceiptText(Reservation reservation, Room room) {
156	        StringBuilder text = new StringBuilder();
157	        text.append("Comprovante de reserva nº ").append(reservation.id()).append('\n');
158	        text.append("Hóspede: ").append(reservation.guest().name()).append(" (CPF ").append(reservation.guest().cpf()).append(")\n");
159	        text.append("Quarto: ").append(room.number()).append(" (").append(room.type()).append(")\n");
160	        text.append("Entrada: ").append(TextFormat.date(reservation.checkIn()))
161	                .append(" | Saída: ").append(TextFormat.date(reservation.checkOut()))
162	                .append(" | ").append(reservation.price().nights()).append(reservation.price().nights() == 1 ? " diária" : " diárias").append('\n');
163	        text.append("Diárias: ").append(TextFormat.money(reservation.price().subtotal())).append('\n');
164	        if (reservation.price().discount().signum() > 0) {
165	            text.append("Desconto: ").append(TextFormat.money(reservation.price().discount())).append('\n');
166	        }
167	        text.append("Total: ").append(TextFormat.money(reservation.price().total())).append('\n');
168	        return text.toString();
169	    }
170	
171	    private static String generateInvoiceText(Reservation reservation, Room room) {
172	        BigDecimal issRetained = reservation.price().subtotal()
173	                .multiply(PriceCalculator.cents(new BigDecimal("5")))
174	                .divide(PriceCalculator.cents(new BigDecimal("100")));
175	
176	        StringBuilder text = new StringBuilder();
177	        text.append("Fatura de hospedagem nº ").append(reservation.id()).append('\n');
178	        text.append("Empresa: ").append(reservation.guest().companyName()).append(" (CNPJ ").append(reservation.guest().companyCnpj()).append(")\n");
179	        text.append("Hóspede: ").append(reservation.guest().name()).append('\n');
180	        text.append("Quarto: ").append(room.number()).append(" (").append(room.type()).append(")\n");
181	        text.append("Entrada: ").append(TextFormat.date(reservation.checkIn()))
182	                .append(" | Saída: ").append(TextFormat.date(reservation.checkOut()))
183	                .append(" | ").append(reservation.price().nights()).append(reservation.price().nights() == 1 ? " diária" : " diárias").append('\n');
184	        text.append("Diárias: ").append(TextFormat.money(reservation.price().subtotal())).append('\n');
185	        text.append("Total: ").append(TextFormat.money(reservation.price().subtotal())).append('\n');
186	        text.append("ISS retido (5%): ").append(TextFormat.money(issRetained)).append('\n');
187	        return text.toString();
188	    }
189	
190	    private static String generateBookingReceiptText(Reservation reservation, Room room) {
191	        java.time.format.DateTimeFormatter isoDate = java.time.format.DateTimeFormatter.ISO_LOCAL_DATE;
192	
193	        StringBuilder text = new StringBuilder();
194	        text.append("Booking receipt no. ").append(reservation.id()).append('\n');
195	        text.append("Guest: ").append(reservation.guest().name()).append(" (passport ").append(reservation.guest().guestPassport())
196	                .append(", ").append(reservation.guest().guestCountry()).append(")\n");
197	        text.append("Room: ").append(room.number()).append(" (").append(room.type()).append(")\n");
198	        text.append("Check-in: ").append(isoDate.format(reservation.checkIn()))
199	                .append(" | Check-out: ").append(isoDate.format(reservation.checkOut()))
200	                .append(" | ").append(reservation.price().nights()).append(reservation.price().nights() == 1 ? " night" : " nights").append('\n');
201	        text.append("Nights: ").append(englishMoney(reservation.price().subtotal())).append('\n');
202	        if (reservation.price().discount().signum() > 0) {
203	            text.append("Discount: ").append(englishMoney(reservation.price().discount())).append('\n');
204	        }
205	        text.append("Total: ").append(englishMoney(reservation.price().total())).append('\n');
206	        return text.toString();
207	    }
208	
209	    private static String englishMoney(BigDecimal amount) {
210	        return "BRL " + String.format(java.util.Locale.US, "%,.2f", amount);
211	    }
212	
213	    private static String confirmationEmailBody(Reservation reservation, String documentText) {
214	        return "Olá, " + reservation.guest().name() + "!\n\n"
215	                + "Sua reserva na " + HOTEL_NAME + " está confirmada. Estes são os dados dela:\n\n"
216	                + documentText + "\n"
217	                + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
218	                + "Até breve!\n";
219	    }
220	
221	    private static HotelException notAllowed(Reservation reservation, String operation) {
222	        return new HotelException(
223	                ErrorCode.OPERATION_NOT_ALLOWED,
224	                "cannot " + operation + " reservation " + reservation.id() + " while it is " + reservation.status());
225	    }
226	}
