    23	/** The HTTP API the inn's website and front desk call. */
    24	public final class HttpApi {
    25	
    26	    private final Javalin server;
    27	    private final Rooms rooms;
    28	    private final ReservationService reservations;
    29	    private final SentMessages sentMessages;
    30	    private final OccupancyReport occupancyReport;
    31	    private final RevenueReport revenueReport;
    32	
    33	    public HttpApi(
    34	            Rooms rooms,
    35	            ReservationService reservations,
    36	            SentMessages sentMessages,
    37	            OccupancyReport occupancyReport,
    38	            RevenueReport revenueReport) {
    39	        this.rooms = rooms;
    40	        this.reservations = reservations;
    41	        this.sentMessages = sentMessages;
    42	        this.occupancyReport = occupancyReport;
    43	        this.revenueReport = revenueReport;
    44	
    45	        ObjectMapper jsonMapper = JsonMapper.builder()
    46	                .addModule(new JavaTimeModule())
    47	                .disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS)
    48	                .build();
    49	        this.server = Javalin.create(config -> {
    50	            config.showJavalinBanner = false;
    51	            config.jsonMapper(new JavalinJackson(jsonMapper, false));
    52	        });
    53	        registerRoutes();
    54	        registerErrorHandling();
    55	    }
    56	
    57	    public Javalin server() {
    58	        return server;
    59	    }
    60	
    61	    private void registerRoutes() {
    62	        server.get("/rooms", ctx -> ctx.json(rooms.all()));
    63	
    64	        server.post("/reservations", ctx -> {
    65	            NewReservation request = readNewReservation(ctx);
    66	            hotel.reservations.Reservation created = reservations.create(request);
    67	            ctx.status(201).json(buildReservationResponse(created, reservations));
    68	        });
    69	        server.get("/reservations/{id}", ctx -> {
    70	            hotel.reservations.Reservation reservation = reservations.find(reservationId(ctx));
    71	            ctx.json(buildReservationResponse(reservation, reservations));
    72	        });
    73	        server.post("/reservations/{id}/confirmation", ctx -> {
    74	            hotel.reservations.Reservation confirmed = reservations.confirm(reservationId(ctx));
    75	            ctx.json(buildReservationResponse(confirmed, reservations));
    76	        });
    77	        server.post("/reservations/{id}/cancellation", ctx -> {
    78	            hotel.reservations.Reservation cancelled = reservations.cancel(reservationId(ctx));
    79	            ctx.json(buildReservationResponse(cancelled, reservations));
    80	        });
    81	        server.post("/reservations/{id}/check-in", ctx -> {
    82	            hotel.reservations.Reservation checkedIn = reservations.checkIn(reservationId(ctx));
    83	            ctx.json(buildReservationResponse(checkedIn, reservations));
    84	        });
    85	        server.post("/reservations/{id}/check-out", ctx ->
    86	                ctx.json(reservations.checkOut(reservationId(ctx))));
    87	        server.get("/reservations/{id}/document", ctx ->
    88	                ctx.json(reservations.receiptCopy(reservationId(ctx))));
    89	
    90	        server.get("/messages", ctx -> ctx.json(sentMessages.all()));
    91	
    92	        server.get("/reports/occupancy", ctx -> {
    93	            LocalDate night = readDate(ctx);
    94	            ctx.contentType("text/csv; charset=utf-8").result(occupancyReport.generate(night));
    95	        });
    96	        server.get("/reports/revenue", ctx -> {
    97	            YearMonth month = readMonth(ctx);
    98	            ctx.contentType("text/csv; charset=utf-8").result(revenueReport.generate(month));
    99	        });
   100	    }
   101	
   102	    private void registerErrorHandling() {
   103	        server.exception(HotelException.class, (exception, ctx) -> {
   104	            ctx.status(httpStatus(exception.errorCode()));
   105	            ctx.json(new ErrorResponse(exception.errorCode().name(), exception.getMessage()));
   106	        });
   107	    }
   108	
   109	    private static int httpStatus(ErrorCode errorCode) {
   110	        return switch (errorCode) {
   111	            case INVALID_REQUEST -> 400;
   112	            case ROOM_NOT_FOUND, RESERVATION_NOT_FOUND -> 404;
   113	            case ROOM_UNAVAILABLE, OPERATION_NOT_ALLOWED -> 409;
   114	            case CAPACITY_EXCEEDED -> 422;
   115	        };
   116	    }
   117	
   118	    private static NewReservation readNewReservation(Context ctx) {
   119	        CreateReservationRequest body;
   120	        try {
   121	            body = ctx.bodyAsClass(CreateReservationRequest.class);
   122	        } catch (Exception unreadableBody) { // Jackson's own exceptions are checked, but reach here unwrapped
   123	            throw new HotelException(ErrorCode.INVALID_REQUEST, "the body is not a valid reservation request");
   124	        }
   125	        if (body == null
   126	                || body.roomNumber() == null
   127	                || isBlank(body.guestName())
   128	                || isBlank(body.guestEmail())
   129	                || body.checkIn() == null
   130	                || body.checkOut() == null
package hotel.documents;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeFormatter;
import java.util.Locale;

/** How money and dates are written in the texts the guest reads (Brazilian Portuguese). */
public final class TextFormat {

    private static final Locale BRAZIL = Locale.forLanguageTag("pt-BR");
    private static final DateTimeFormatter BRAZILIAN_DATE = DateTimeFormatter.ofPattern("dd/MM/yyyy");

    private TextFormat() {
    }

    public static String money(BigDecimal amount) {
        return "R$ " + String.format(BRAZIL, "%,.2f", amount);
    }

    public static String date(LocalDate date) {
        return BRAZILIAN_DATE.format(date);
    }
}
package hotel.reservations;

import hotel.rooms.Room;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.time.Month;

/**
 * The price of a stay: every night costs the room's nightly rate, plus the high-season surcharge on
 * high-season nights; the rate plan may then give a discount on the sum. Money is rounded to cents
 * (half-even) at every step.
 */
public final class PriceCalculator {

    static final BigDecimal HIGH_SEASON_SURCHARGE = new BigDecimal("0.20");
    static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");

    public Price calculate(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan) {
        int nights = 0;
        BigDecimal subtotal = cents(BigDecimal.ZERO);
        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
            subtotal = subtotal.add(nightPrice(room, night));
            nights++;
        }
        BigDecimal discount = switch (ratePlan) {
            case STANDARD -> cents(BigDecimal.ZERO);
            case NON_REFUNDABLE -> cents(subtotal.multiply(NON_REFUNDABLE_DISCOUNT));
        };
        return new Price(nights, subtotal, discount, subtotal.subtract(discount));
    }

    BigDecimal nightPrice(Room room, LocalDate night) {
        BigDecimal nightlyRate = room.nightlyRate();
        if (isHighSeason(night)) {
            return cents(nightlyRate.multiply(BigDecimal.ONE.add(HIGH_SEASON_SURCHARGE)));
        }
        return cents(nightlyRate);
    }

    /** High season: from December 15 to the end of February, and the whole of July. */
    static boolean isHighSeason(LocalDate date) {
        Month month = date.getMonth();
        return month == Month.JANUARY
                || month == Month.FEBRUARY
                || month == Month.JULY
                || (month == Month.DECEMBER && date.getDayOfMonth() >= 15);
    }

    static BigDecimal cents(BigDecimal value) {
        return value.setScale(2, RoundingMode.HALF_EVEN);
    }
}
